import chess
import chess.engine
import chess.pgn
import math
import matplotlib.pyplot as plt


def g_mean(array):
    product = 1
    for i in array:
        product *= i
    product **= 1 / len(array)

    return product


def sd(array):
    if len(array) == 0:
        return -1
    mean = sum(array) / len(array)
    t = 0
    for i in range(len(array)):
        t += (array[i] - mean)**2
    t /= len(array)+1
    return t

def mean_change(array):
    mc = 0
    for i in range(len(array) - 1):
        mc += abs(array[i + 1] - array[i])
    mc /= len(array) - 1
    return mc


def eval_risk(eng, board):
    score = []
    with eng.analysis(board, chess.engine.Limit(depth=10)) as analysis:
        # Get some info then stop
        for info in analysis:
            if type(info.get("score")) is chess.engine.PovScore:
                if type(info.get("score").white().score()) is int:
                    score.append(info.get("score").white().score() / 100)
                else:
                    score.append(10)
    ac = mean_change(score)
    return ac


def visualize(game, game_main, tool_risk, c_scheme):
    for i in range(len(tool_risk)):
        tool_risk[i] = math.log(tool_risk[i] + 1.0001)
    colors = []
    c = True
    for i in range(len(tool_risk)):
        if c:
            colors.append(c_scheme[0])
        else:
            colors.append(c_scheme[1])
        c = not c
    game_num = int(game.headers['Round'].split(".")[0])
    ax = plt.gca()
    ax.set_facecolor("green")
    plt.scatter(list(range(len(tool_risk))), tool_risk, c=colors)

    # for i in range(len(game_main)):
    #     print(f"{colors[i]} - {game_main[i].uci()}: {tool_risk[i]}")


def ana_risk(engine, pgn):
    with open(pgn) as pgn_file:
        game = chess.pgn.read_game(pgn_file)
    board = game.board()

    previous = eval_risk(engine, board)
    game_main = list(game.mainline_moves())
    print(f"Game {game.headers['Round']}")

    game_risk = []
    comp_risk = []
    comp_main = []
    for i in range(len(game_main)):
        info = engine.analyse(board, chess.engine.Limit(depth=15))
        comp_main.append(info['pv'][0])
        board.push(info['pv'][0])
        virtual_risk = eval_risk(engine, board)
        comp_risk.append(virtual_risk * 1 / (math.log(previous + 1.0001)))
        board.pop()

        move = game_main[i]
        board.push(move)
        if (move != info['pv'][0]):
            board_risk = eval_risk(engine, board)
        else:
            board_risk = virtual_risk

        game_risk.append(board_risk * 1 / (math.log(previous + 1.0001)))
        previous = board_risk * 1 / math.log(previous + 1.0001)

    game_num = int(game.headers['Round'].split(".")[0])
    # plt.figure(num=game_num)
    # visualize(game, game_main, game_risk, ['white', 'white'], "human")
    # visualize(game, game_main, comp_risk, ['black', 'black'], "computer")
    # plt.title(f"Game {game_num}'s Risky Factors for Each Move")
    # plt.ylabel("Risky")
    # plt.xlabel("Move Number")
    # plt.legend()
    # plt.savefig(f"Risk2Test{game_num}.png")
    diff_risk = []
    for i in range(len(game_risk)):
        diff_risk.append(math.tanh(game_risk[i]) - math.tanh(comp_risk[i]))
    plt.figure(num=game_num, figsize=(10, 6))
    visualize(game, game_main, diff_risk, ['white', 'black'])
    # plt.scatter(list(range(len(game_risk))), diff_risk, c="black")
    plt.title(f"Game {game_num}'s Difference between Human and Computer's Risky Factor for Each Move")
    plt.ylabel("Risky")
    plt.xlabel("Move Number")
    plt.ylim([-1.1, 1.1])
    plt.savefig(f"Risk2Diff{game_num}.png")
    #
    return game_main, game_risk, comp_main, comp_risk


